def linear_search(arr, target):
    count = 0
    for i in range(len(arr)):
        count += 1                  # 비교 한 번
        if arr[i] == target:
            return i, count
    return -1, count

arr = [9, 5, 8, 3, 7]
for t in (9, 8, 7, 6):
    print(f'{t} 찾기 → 위치 {linear_search(arr, t)[0]}, 비교 {linear_search(arr, t)[1]}번')

cards = [3, 7, 1, 9, 4, 6]
checked = 0
found = []
for i in range(len(cards)):
    for j in range(i + 1, len(cards)):
        checked += 1
        if cards[i] + cards[j] == 10:
            found.append((cards[i], cards[j]))
print('합이 10인 짝:', found)
print('살펴본 짝의 수:', checked)
